#!/usr/bin/env bash
wait_active(){ local u="$1" t="${2:-30}" i; for ((i=0;i<t;i++)); do systemctl is-active --quiet "$u"&&return 0; sleep 1; done; systemctl status "$u" --no-pager||true; return 1; }
nut_health_target(){ case "$PROFILE" in remote-client) printf '%s@%s\n' "$UPS_NAME" "$NUT_HOST";; *) printf '%s@localhost\n' "$UPS_NAME";; esac; }
installation_health_gate(){ log "running post-install health gate"; if [[ "$OPERATING_MODE" == armed ]]; then "$LIBEXEC_DIR/cockpit-ups-wolctl" config-validate <"$ETC_DIR/config.yaml" >/dev/null||die "armed host prerequisite validation failed"; fi; wait_active cockpit-ups-wol-agent.service 30||die "agent failed startup health gate"; systemctl is-enabled --quiet cockpit-ups-wol-agent.service||die "agent is not enabled"; systemctl is-enabled --quiet cockpit-ups-wol-health.timer||die "health timer is not enabled"; wait_active cockpit-ups-wol-health.timer 15||die "health timer inactive"; if unit_exists cockpit.socket; then systemctl is-enabled --quiet cockpit.socket||die "cockpit.socket not enabled"; fi; if command -v upsc>/dev/null; then local target end; target="$(nut_health_target)"; end=$((SECONDS+30)); while ((SECONDS<end)); do upsc "$target">/dev/null 2>&1&&break; sleep 2; done; upsc "$target">/dev/null 2>&1||die "NUT health check failed for $target"; fi; local probation="${COCKPIT_UPS_WOL_PROBATION_SECONDS:-60}"; [[ "$probation" =~ ^[0-9]+$ ]]||die "invalid COCKPIT_UPS_WOL_PROBATION_SECONDS"; log "starting ${probation}-second probation"; local end=$((SECONDS+probation)); while ((SECONDS<end)); do systemctl is-active --quiet cockpit-ups-wol-agent.service||die "agent failed during probation"; "$LIBEXEC_DIR/cockpit-ups-wolctl" health >/dev/null 2>&1||die "agent health IPC failed during probation"; sleep 1; done; log "post-install probation passed"; }
